/**
 * Resolves the in-app hrefs that notifications and search hits carry. Routes
 * are built by `@/lib/url`; this module only loads the slugs and the issue
 * number those builders need.
 */
import { issuePath, orgPath, projectPath, settingsPath } from "@/lib/url";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import type { CommentId, IssueId, OrgId, ProjectId } from "@/types/common";

async function orgSlugOf(orgId: OrgId): Promise<string | null> {
  return (await orgRepo.findOrgById(orgId))?.slug ?? null;
}

/** The issue's own page, or the org's issue list when the issue is gone. */
export async function issueHref(orgId: OrgId, issueId: IssueId): Promise<string> {
  const orgSlug = await orgSlugOf(orgId);
  if (orgSlug === null) return "/orgs";

  const issue = await issueRepo.findIssueById(orgId, issueId);
  const project = issue
    ? await projectRepo.findProjectById(orgId, issue.projectId)
    : null;
  if (!issue || !project) return orgPath(orgSlug, "issues");

  return issuePath(orgSlug, project.slug, issue.number);
}

export async function projectHref(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<string> {
  const orgSlug = await orgSlugOf(orgId);
  if (orgSlug === null) return "/orgs";

  const project = await projectRepo.findProjectById(orgId, projectId);
  return project
    ? projectPath(orgSlug, project.slug)
    : orgPath(orgSlug, "projects");
}

/** A comment lives on its issue's page. */
export async function commentHref(
  orgId: OrgId,
  commentId: CommentId,
): Promise<string> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (!comment) {
    const orgSlug = await orgSlugOf(orgId);
    return orgSlug === null ? "/orgs" : orgPath(orgSlug, "issues");
  }
  return issueHref(orgId, comment.issueId);
}

export async function settingsHref(
  orgId: OrgId,
  section: "members" | "billing",
): Promise<string> {
  const orgSlug = await orgSlugOf(orgId);
  return orgSlug === null ? "/orgs" : settingsPath(orgSlug, section);
}
