  // Only a refused write emits this event. The owner hears about it whoever
  // tried, and one unread alert per resource is enough until it has been read.
  subscribe("billing.limit_exceeded", async (payload) => {
    const org = await orgRepo.findOrgById(payload.orgId);
    if (!org) return;

    const label = LIMIT_LABELS[payload.resource];
    const title = `Plan limit reached: ${label}`;

    const pending = await notificationRepo.findUnread(
      payload.orgId,
      org.ownerId,
      "plan_limit_reached",
      title,
    );
    if (pending) return;

    await notify(
      payload.orgId,
      "plan_limit_reached",
      [org.ownerId],
      {
        title,
        body: `Your ${org.plan} plan has no room for more ${label} (${payload.used} of ${payload.limit} in use)`,
        href: await settingsHref(payload.orgId, "billing"),
        actorId: payload.actorId,
      },
      { includeActor: true },
    );
  });
}

registerFanOut();
