          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owner is told who joined; the person who joined is never told about
  // themselves (`notify` drops the actor, and the actor here is the joiner).
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: await settingsHref(payload.orgId, "members"),
      actorId: payload.userId,
    });
  });

  // Only a refused write emits this event. The owner hears about it whoever
  // tried, and one unread alert per resource is enough until it has been read.
  subscribe("billing.limit_exceeded", async (payload) => {
    const org = await orgRepo.findOrgById(payload.orgId);
    if (!org) return;

    const label = LIMIT_LABELS[payload.resource];
    const title = `Plan limit reached: ${label}`;

    const pending = await notificationRepo.findUnread(
      payload.orgId,
      org.ownerId,
      "plan_limit_reached",
      title,
    );
    if (pending) return;

    await notify(
      payload.orgId,
      "plan_limit_reached",
      [org.ownerId],
      {
        title,
        body: `Your ${org.plan} plan has no room for more ${label} (${payload.used} of ${payload.limit} in use)`,
        href: await settingsHref(payload.orgId, "billing"),
        actorId: payload.actorId,
      },
      { includeActor: true },
    );
  });
}

