vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as ns from "@/server/services/notification-service";
import * as invitationService from "@/server/services/invitation-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
const log = (x: unknown) => appendFileSync("/tmp/zz.log", JSON.stringify(x) + "\n");
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("works", async () => {
  const t = await createTenant("tmp", "free");
  const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.viewer }));
  await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issue.id, status: "done" });
  const list = (a: any, u: any) => ns.listNotifications(a, { orgId: t.org.id, recipientId: u, unreadOnly: false, limit: 25, cursor: null });
  log((await list(t.actors.viewer, t.userIds.viewer)).items.map((i) => [i.kind, i.href]));
  await expect(list(t.actors.admin, t.userIds.viewer)).rejects.toThrow();
  const mk = (n: string) => projectService.createProject(t.actors.admin, { orgId: t.org.id, name: n, slug: n, key: n.toUpperCase(), description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null });
  await mk("second"); await mk("third").catch(() => {}); await mk("fourth").catch(() => {});
  await invitationService.inviteMember(t.actors.admin, { orgId: t.org.id, email: "a@b.test", role: "member" }).catch(() => {});
  const o = await list(t.actors.owner, t.userIds.owner);
  log(o.items.map((i) => [i.kind, i.title, i.href]));
  await ns.markAllRead(t.actors.owner, t.org.id);
  await mk("fifth").catch(() => {});
  log((await list(t.actors.owner, t.userIds.owner)).items.length);
  const r = await searchService.search(t.actors.member, { orgId: t.org.id, q: "Issue", limit: 25, cursor: null } as any).catch((e) => e);
  log(r.items?.map((i: any) => i.href) ?? String(r));
});
EOF
rm -f /tmp/zz.log; npx vitest run tests/services/zz-tmp.test.ts 2>&1 | grep -v "npm warn" | tail -15; cat /tmp/zz.log; rm tests/services/zz-tmp.test.ts

